-- aar/w3/aar_row_607_draft2.sql. DRAFT 2 by W3 (session_01H1X3ANsGiMnhnbkfphocmo) for the coordinator (seat 36). NOT RUN by W3. Draft 1 f401373c: W1 PASS (Wall 11760). ONE CHANGE, on W4's answer at Wall 11759: W4 corrected notes607.md (f4a99e70 to 4f5fdd43; the base fetch was 15:50:53 to 15:50:57 CST, not "about 16:10"), so the build_files entry and the comment below cite the corrected file. W4 confirmed the revert note. For a W1 confirmation, then the operator's card, then the insert from seat 36.
-- One ask_aar_snapshots row for ASK 607 (a gate change in no line form the engine reads is recorded, not counted) and its ask_aar_builders row.
-- Sources: the Wall posts named (11717 to 11720, 11725 to 11728, 11730, 11732, 11733, 11738, 11741 to 11743, 11748, 11751, 11754, 11755; 11717 to 11728 read by W3 in their first 1,500 characters, the rest in full); W4's files under /mnt/project-files/ask607/w4/ (md5sum by W3, 16:3x CST 2026-11-24); the plan head and notes607.md read in full; audit_log 41703 and 41725 read in full; md_notes_rulings rows 546 and 547; the two cards read in W4's thread and W3's thread; engine_manual_log rows 329 and 330.
-- NOT CHECKED BY W3: the Shared Library node md5s (from notes607.md); W4's c1 to c4 outputs were not re-run by W3 (W1 re-ran them, Wall 11741).
-- A DEFECT IN A SOURCE, corrected by W4: notes607.md as graded (f4a99e70) and Wall 11738 (posted 15:57 CST) gave the base fetch as "about 16:10 CST", a time after the post. W4 states the true fetch time as 15:50:53 to 15:50:57 CST and corrected the notes (4f5fdd43; Wall 11759). The base files are md5-equal to the ASK 608 fetch-backs (89618718, acbd7433), and W1 found the base equal to live (Wall 11741).
-- objective_met is 'in part': written, read back, manual written and read back; UNEXERCISED by a run (gate form refusals are rare; the two-live-runs rule applies).
-- After the insert: SELECT * FROM ask_aar_snapshots_check(); SELECT * FROM ask_aar_grades_check();
-- The session line below must be the coordinator's own session; written_by is read from it.
BEGIN;
SET LOCAL truth.session_id = '<COORDINATOR SESSION, registered to seat 36>';
WITH s AS (
INSERT INTO ask_aar_snapshots (ask, rev, title, objective, objective_met, objective_met_reason, objective_source, written_by, prior_row, operator_words, card, owner_seat, plan, build_files, revert, grades, md5_written, audit_ids, objects, tests, readbacks, run_evidence, manuals, status, sources)
VALUES (607, '1', 'ASK 607: a gate change in no line form the engine reads is recorded, not counted',
  $t$When a judge answers a NOT APPLIED item at the gate with a CHANGE TO that the engine cannot read as any line form, the refusal is stored with its reason, and the judge's line before the change stands. The item is recorded only (live false); it is not counted in drv_uncured and does not count toward removing the seat. This is the same treatment ASK 549 gives the pkgPS and pkgSGA refusals. (plan rev 0, OBJECTIVE, ask607/w4/plan607.md 34db6c5d)$t$,
  'in part',
  $t$Written by W4 at 16:00 CST 2026-11-24 on the card "Write it" in W4's thread (Wall 11742; audit 41703). One Library line, the same in engine and child (LIB line 1434): in sbApply2024 the refusal push "the CHANGE TO line has no line form the engine reads" gains rfs:'pkgFRM' with an ASK 607 tag (+94 characters); MAP n +94 on the 13 entries that hold the line; library sha 802077b0878612c9 to 2f5aa1e63d51edb1. Only the Shared Library node changed in each workflow: engine 94b682a0 to 0d55aab1-e709-4f2f-8430-8e8887a6be19, child b9cd4e5c to 74353c40-005b-466d-bb7f-c36b157f37d2. No prompt text and no model setting changed; nothing deleted; the gate prompt sentence is untouched. The only reader of the mark is the ASK 549 reader in gateCure2024's NOT APPLIED branch, so such a refusal is stored UNCURED and record-only with the engine's reason, the judge's line before the change stands (a grant line the judge itself disowned included), and no seat is removed for it. W1 readback MATCH (Wall 11743). The engine manual entry was written by W3 at 16:27 CST on its own card (part 11.2 v309; Wall 11754; audit 41725; W1 readback MATCH, Wall 11755). Shown offline on stored rows: luna, judgment 1122, enforcer rows 29285 to 29295, eleven counted before and none after. Unchanged and shown so: a KEEP, a silent item, applied changes, the pkgSGA and pkgPS refusals, row 31511 (a placement refusal, left out of the class as unsettled), the chatgpt rows 7218 to 7224 (not form refusals on today's engine). Limits: the judge text at gate time is not stored, so the replay used the stored final text; a form refusal on a gate item of another kind would still count (at the write the stored record held none); a judge could now leave an item standing by an unreadable change, which the operator was shown on the ruling card. Not shown by a run: no run since the write. Open: two clean live runs (the operator's rule of 10:38 CST 2026-11-24); the mark of the change in a run is an E-GATE row whose result reads "pkgFRM refused the gate change ... (RECORD-ONLY)", and runs without a gate form refusal leave it UNEXERCISED.$t$,
  '11717, 11718, 11719, 11720, 11725, 11726, 11727, 11728, 11730, 11732, 11733, 11738, 11741, 11742, 11743, 11748, 11751, 11754, 11755, 11759',
  current_setting('truth.session_id'), NULL,
  to_jsonb($t$The operator's part is three card presses. (1) The ruling card in W3's thread, "Rule on a judge's gate change the engine cannot read?" (card cmsg_017ZQamDMHrS6fqMHnQDVo58X84T7LagpgxuCC7LtcFUJw): he pressed "Record-only, as ASK 549" at 15:33 CST 2026-11-24 (md_notes_rulings row 546 of seat 33). The option's words: "W4 plans it: the refusal is stored with its reason, the judge's line stays as it was, and nothing counts toward removing the seat." The other choices were "Count it, as now" and "Hold". (2) W4's write card "Write ASK 607 (gate form refusal recorded, not counted) to live now?" (cmsg_017ZQamDMHrS6fqMHnQDVo585pU7PM4ST1GC7wfh4inWXD): he pressed "Write it" at 16:00 CST. (3) W3's manual card "Write the engine manual entries for ASK 607 and ASK 623?" (cmsg_017ZQamDMHrS6fqMHnQDVo58HchLDxYapz2pmrm9hZXW9c): he pressed "Write both entries" at 16:24 CST (md_notes_rulings row 547 of seat 33). No other words of his on this ASK are in the record W3 read.$t$::text),
  $j${"answer": "Write it", "question": "Write ASK 607 (gate form refusal recorded, not counted) to live now?", "thread": "W4", "card_id": "cmsg_017ZQamDMHrS6fqMHnQDVo585pU7PM4ST1GC7wfh4inWXD", "press_time": "16:00 CST 2026-11-24 (22:00:59Z)", "source": "the card and its press read by W3 in W4's thread; Wall 11742; audit 41703", "ruling_card": {"card_id": "cmsg_017ZQamDMHrS6fqMHnQDVo58X84T7LagpgxuCC7LtcFUJw", "question": "Rule on a judge's gate change the engine cannot read?", "answer": "Record-only, as ASK 549", "press_time": "15:33 CST 2026-11-24", "thread": "W3", "source": "md_notes_rulings row 546 of seat 33; Wall 11730"}, "manual_card": {"card_id": "cmsg_017ZQamDMHrS6fqMHnQDVo58HchLDxYapz2pmrm9hZXW9c", "question": "Write the engine manual entries for ASK 607 and ASK 623?", "answer": "Write both entries", "press_time": "16:24 CST 2026-11-24", "thread": "W3", "source": "md_notes_rulings row 547 of seat 33"}}$j$::jsonb,
  'W4',
  $j${"md5": "34db6c5d", "path": "ask607/w4/plan607.md", "commit": "55a51fcc", "note": "plan rev 0, in the ASK FORM; the one push site, the one reader of the mark, and the rows left out of the class (31511; 7218 to 7224; a form refusal on another kind of gate item)", "source": "Wall 11732, 11733; md5sum by W3"}$j$::jsonb,
  $j$[{"md5": "46a1862b", "path": "ask607/w4/b1/target_engine_607.json", "note": "the engine target; only the Shared Library differs from the base", "source": "md5sum by W3; notes607.md; Wall 11741"}, {"md5": "b367f537", "path": "ask607/w4/b1/target_child_607.json", "note": "the child target; only the Shared Library differs from the base", "source": "md5sum by W3; notes607.md; Wall 11741"}, {"md5": "3bd84fec", "path": "ask607/w4/b1/build607.cjs", "note": "builds both targets from the base", "source": "md5sum by W3"}, {"md5": "4f5fdd43", "path": "ask607/w4/b1/notes607.md", "note": "build notes, rev 0, as corrected by W4 after the write: the base fetch time reads 15:50:53 to 15:50:57 CST; W1 graded the notes as f4a99e70, which gave \"about 16:10 CST\" in error", "source": "md5sum by W3; f4a99e70 read in full by W3; Wall 11759"}, {"md5": "1115d58c", "path": "ask607/w4/b1/c1_607.cjs", "note": "C1; as it stands after W1's N1 (the test path); W1 graded the earlier text, W3 did not diff", "source": "md5sum by W3; Wall 11741; W4's checklist (git 512e5f02)"}, {"md5": "0e915b2c", "path": "ask607/w4/b1/c2_607.cjs", "note": "C2 controls", "source": "md5sum by W3"}, {"md5": "da0fa0e8", "path": "ask607/w4/b1/c3_607.cjs", "note": "C3 send-back stage", "source": "md5sum by W3"}, {"md5": "9db95560", "path": "ask607/w4/b1/data607.json", "note": "stored judge texts, gate replies and flagged lines read from the database", "source": "md5sum by W3"}, {"md5": "027dd197", "path": "ask607/w4/b1/out_c1_607.txt", "note": "C1 output; write/c1_at_write.txt has the same md5", "source": "md5sum by W3"}, {"md5": "18279382", "path": "ask607/w4/b1/out_c2_607.txt", "note": "C2 output; write/c2_at_write.txt has the same md5", "source": "md5sum by W3"}, {"md5": "73d8cfae", "path": "ask607/w4/b1/out_c3_607.txt", "note": "C3 output; write/c3_at_write.txt has the same md5", "source": "md5sum by W3"}, {"md5": "e5479c9f", "path": "ask607/w4/b1/out_c4_607.txt", "note": "C4 stored-row count with its SQL", "source": "md5sum by W3"}, {"md5": "f167e3a9", "path": "ask607/w4/write/write607.sh", "note": "the write script; replaces only the Shared Library on each live workflow; fails closed at every gate (W1)", "source": "md5sum by W3; notes607.md; Wall 11741"}, {"md5": "d31df09a", "path": "ask607/w4/write/fetchback_eng_607.json", "note": "engine fetch-back after the write (0d55aab1)", "source": "md5sum by W3; audit 41703"}, {"md5": "e50c2137", "path": "ask607/w4/write/fetchback_child_607.json", "note": "child fetch-back after the write (74353c40)", "source": "md5sum by W3; audit 41703"}, {"md5": "6ec71717", "path": "ask607/w4/write/standing_at_write.txt", "note": "standing set at the write: 31 PASS, 0 FAIL", "source": "md5sum and last lines read by W3"}]$j$::jsonb,
  $j${"engine": {"path": "ask607/w4/write/revert_eng_607.json", "md5": "bfc80b17", "note": "saved by write607.sh before the PUT; not rehearsed"}, "child": {"path": "ask607/w4/write/revert_child_607.json", "md5": "7491b58c", "note": "saved by write607.sh before the PUT; restored together with the engine; not rehearsed"}, "database": "none: no database object was changed", "note": "ASK 623 was written to the engine one minute later; a revert of ASK 607 alone restores only the Shared Library node of each workflow, not the whole revert file", "source": "audit 41703; md5sum by W3; the note on ASK 623 is W3's reading of the write order"}$j$::jsonb,
  $j$[{"seat": "W1", "verdict": "PASS WITH N1 (plan rev 0)", "wall_id": 11733, "md5_graded": "34db6c5d", "verdict_norm": "PASS", "source": "Wall 11733; fairjudge/w1/g607/grade_plan607_rev0.md (commit 5b52b915)"}, {"seat": "W1", "verdict": "PASS WITH N1 (build rev 0)", "wall_id": 11741, "md5_graded": "46a1862b", "verdict_norm": "PASS", "source": "Wall 11741; fairjudge/w1/g607/grade_build607_rev0.md be000779 (commit 7a040c29); the child target b367f537 was graded with it"}, {"seat": "W1", "verdict": "PASS WITH N1, N2 (manual pairs draft 2, ASK 607 and 623 together)", "wall_id": 11748, "md5_graded": "6721facf", "verdict_norm": "PASS", "source": "Wall 11748; fairjudge/w1/g623/grade_manual607_623_d2.md 38b3477b (commit 62c26741)"}, {"seat": "W1", "verdict": "PASS (manual pairs draft 3)", "wall_id": 11751, "md5_graded": "3ac16429", "verdict_norm": "PASS", "source": "Wall 11751"}]$j$::jsonb,
  ARRAY['46a1862b', 'b367f537'], '[41703, 41725]'::jsonb,
  $j$[{"kind": "n8n workflow", "name": "ORACLE_DEBATE_V1 moMxiV4Irg1uRBZN", "before": "94b682a0", "after": "0d55aab1-e709-4f2f-8430-8e8887a6be19 (then 20db58ee by ASK 623 at 16:01 CST)"}, {"kind": "n8n node", "name": "Shared Library (engine)", "before": "00a5653f, library sha 802077b0878612c9", "after": "e65629eb, library sha 2f5aa1e63d51edb1 (node md5s from notes607.md)"}, {"kind": "n8n workflow", "name": "child MqQHRl7mQQ0z8QdT", "before": "b9cd4e5c", "after": "74353c40-005b-466d-bb7f-c36b157f37d2"}, {"kind": "n8n node", "name": "Shared Library (child)", "before": "19d1ecb3", "after": "72757492 (node md5s from notes607.md)"}, {"kind": "engine manual part", "name": "11.2", "before": "v242 6b4d83aa, 14,690", "after": "v309 c3c29600, 16,643"}]$j$::jsonb,
  $j$[{"name": "C1 (c1_607.cjs): the real gateCure2024 of Gate Record on stored judge text, gate reply and flagged lines", "result": "luna, judgment 1122, rows 29285 to 29295: each UNCURED and counted before; after, each UNCURED and record-only with the pkgFRM reason; counted 11 before, 0 after. chatgpt, judgment 988, rows 7218 to 7224: old and new give the same row for all seven. The judge text used is the stored final text; the gate-time text is not stored.", "source": "notes607.md; out_c1_607.txt; W1's own run, Wall 11741"}, {"name": "C2 controls (c2_607.cjs)", "result": "each the same old and new: a KEEP stays CURED; a silent item stays UNCURED and counted; the applied changes of rows 29283 and 29284 stay CURED; a pkgSGA and a pkgPS refusal stay record-only under their own names; row 31511 is never record-only", "source": "notes607.md; out_c2_607.txt; W1's own run, Wall 11741"}, {"name": "C3 send-back stage (c3_607.cjs), judgment 1272, gemini S1 to S17", "result": "lines whole: equal old and new; lines cut at 1,500: equal except rfs:'pkgFRM' on S13; the mark is carried and not read at this stage", "source": "notes607.md; out_c3_607.txt; W1's own run, Wall 11741"}, {"name": "C4 stored-row count", "result": "25 stored counted gate form refusals, all on NOT APPLIED items; 0 on items of other kinds", "source": "out_c4_607.txt; W1's SQL, Wall 11741"}, {"name": "Standing set with compile-all, and pair Library Check", "result": "31 PASS, 0 FAIL (290 of 290 engine, 67 of 67 child); pair PASSES on 2f5aa1e63d51edb1; at the build, at the write, and on W1's fetch", "source": "standing_at_write.txt; Wall 11741, 11742, 11743"}, {"name": "Before the plan: the 30 old refused gate changes on the live apply step (r607b.cjs, minimal texts, one per form)", "result": "11 applied today; 7 engine-made (7218 to 7224); 11 still refused as the judge's own form (29285 to 29295); 1 unsettled (31511). Row 53202 of run 42071 was engine-made (r607.cjs).", "source": "Wall 11719, 11725, 11726, 11728; out_r607.txt d6c07246; out_r607b.txt 0d7abe8e"}]$j$::jsonb,
  $j$[{"seat": "W1", "result": "MATCH (W1's own live fetch: engine 20db58ee equals the 607 target with the five ASK 623 nodes, 0 nodes differ; child 74353c40 equals the 607 target, 0 differ; standing 31/0; pair PASSES on 2f5aa1e63d51edb1)", "wall_id": 11743, "source": "Wall 11743; fairjudge/w1/g623/readback_write607_623.md 4f38ed7d (commit 457b39ed)"}, {"seat": "W1", "result": "MATCH (engine manual: 11.2 v309 c3c2960035a406a6c8949aaecf386c6f, 16,643, equal to draft 3 applied to base v242 6b4d83aa with the old text found once; whole manual v310, 756,361 characters)", "wall_id": 11755, "source": "Wall 11755"}]$j$::jsonb,
  $j${"case": "UNEXERCISED: no run since the write (debate_results last row 13:48 CST 2026-11-24, run 42283). Mark: an E-GATE row whose cure_reason begins \"GATE CHANGE TO\" and whose result reads \"pkgFRM refused the gate change ... (RECORD-ONLY)\", with no seat removed for it. A run with no gate form refusal leaves the change unexercised. Two clean live runs are owed.", "source": "notes607.md; Wall 11743; W3's SQL at 16:29 CST"}$j$::jsonb,
  $j${"op_doc": "none", "engine_manual": "WRITTEN by W3 at 16:27 CST 2026-11-24 on the card \"Write both entries\" (pressed 16:24 CST; ruling row 547 of seat 33): part 11.2 v309 c3c2960035a406a6c8949aaecf386c6f (16,643; log row 329; base v242 6b4d83aa, 14,690); one new entry, ASK 607, A GATE CHANGE IN NO LINE FORM THE ENGINE READS DOES NOT REMOVE THE SEAT, between the ASK 549 entry and the ASK 561 entry; nothing removed. Pairs manual1123/w3/a607_623/em_pairs_607_623_draft3.json 3ac16429 (commit 7f100b2b), W1 PASS Wall 11751. Wall 11754; audit 41725. W1's readback: MATCH, Wall 11755."}$j$::jsonb,
